declare(strict_types=1); require __DIR__.'/../config/bootstrap.php';
$page=$_GET['page']??'dashboard';
if($page==='logout'){Auth::logout();redirect('index.php?page=login');}
if($page==='login'){ if(current_user()) redirect('index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ if(Auth::login(post('email'),post('password'))) redirect('index.php'); $error='E-mail ou senha inválidos.'; } ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar · Inova CRM</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><img src="assets/logo-inova-crm.png" alt="Inova CRM" class="login-logo"><p class="tagline">Conecte. Organize. Cresça.</p><h1>Bem-vindo de volta</h1><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><label>E-mail<input type="email" name="email" required autofocus></label><label>Senha<input type="password" name="password" required></label><button class="btn primary">Entrar no painel</button></form><p class="hint">Configure o banco e crie o primeiro administrador conforme o README.</p></div></body></html><?php exit; }
require_login(); if($page==='admin') require_admin();
if($page==='customers') customers_page(); elseif($page==='deals') deals_page(); elseif($page==='tasks') tasks_page(); elseif($page==='admin') admin_page(); else dashboard_page();
function dashboard_page():void { layout_start('Dashboard'); $cid=tenant_id();$stats=[];$stats['customers']=count_tenant('customers');$stats['deals']=count_tenant('deals', "stage NOT IN ('won','lost')");$stats['tasks']=count_tenant('tasks', "status='pending'");$q=db()->prepare('SELECT COALESCE(SUM(value_cents),0) FROM deals WHERE company_id=? AND stage NOT IN ("lost")');$q->execute([$cid]);$pipeline=(int)$q->fetchColumn();$recent=db()->prepare('SELECT title,value_cents,stage FROM deals WHERE company_id=? ORDER BY created_at DESC LIMIT 5');$recent->execute([$cid]); ?><section class="hero"><div><span class="eyebrow">VISÃO GERAL</span><h2>Olá, <?=e(current_user()['name'])?>.</h2><p>Aqui está um resumo do seu dia no Inova CRM.</p></div><a class="btn primary" href="index.php?page=customers&new=1">+ Novo cliente</a></section><div class="stats"><div class="stat"><span>Clientes</span><strong><?=$stats['customers']?></strong><small>de <?=plan_limits()['customers']?> no plano</small></div><div class="stat"><span>Oportunidades abertas</span><strong><?=$stats['deals']?></strong><small>pipeline ativo</small></div><div class="stat"><span>Valor do pipeline</span><strong>R$ <?=number_format($pipeline/100,2,',','.')?></strong><small>em oportunidades</small></div><div class="stat"><span>Tarefas pendentes</span><strong><?=$stats['tasks']?></strong><small>acompanhe seus próximos passos</small></div></div><div class="grid-2"><section class="card"><div class="card-head"><h3>Oportunidades recentes</h3><a href="index.php?page=deals">Ver todas</a></div><table><thead><tr><th>Título</th><th>Etapa</th><th>Valor</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?=e($r['title'])?></td><td><span class="badge <?=e($r['stage'])?>"><?=e(stage_label($r['stage']))?></span></td><td>R$ <?=number_format($r['value_cents']/100,2,',','.')?></td></tr><?php endforeach; ?></tbody></table></section><section class="card accent"><span class="eyebrow">SUA MARCA</span><h3>Mais do que um CRM,<br>um parceiro para o seu <em>crescimento.</em></h3><div class="line"></div><p>Organize seus relacionamentos, acompanhe oportunidades e transforme conexões em resultados.</p></section></div><?php layout_end(); }
function customers_page():void { if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(limit_reached('customers')){flash('error','Limite de clientes do plano atingido.');redirect('index.php?page=customers');}$q=db()->prepare('INSERT INTO customers(company_id,name,email,phone,organization,source,notes) VALUES(?,?,?,?,?,?,?)');$q->execute([tenant_id(),post('name'),post('email'),post('phone'),post('organization'),post('source'),post('notes')]);flash('success','Cliente cadastrado.');redirect('index.php?page=customers');} layout_start('Clientes');$q=db()->prepare('SELECT * FROM customers WHERE company_id=? ORDER BY created_at DESC');$q->execute([tenant_id()]);$rows=$q->fetchAll(); ?><div class="page-actions"><p>Relacionamentos mais fortes começam com organização.</p><a class="btn primary" href="?page=customers&new=1">+ Novo cliente</a></div><?php if(isset($_GET['new'])): ?><section class="card form-card"><h3>Novo cliente</h3><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><?php fields_customer(); ?><button class="btn primary">Salvar cliente</button></form></section><?php endif; ?><section class="card"><div class="card-head"><h3>Todos os clientes</h3><span class="counter"><?=count($rows)?> registros</span></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Organização</th><th>Contato</th><th>Origem</th><th>Cadastro</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['organization']?:'—')?></td><td><?=e($r['email']?:$r['phone']?:'—')?></td><td><?=e($r['source']?:'—')?></td><td><?=e(date('d/m/Y',strtotime($r['created_at'])))?></td></tr><?php endforeach; ?></tbody></table></div></section><?php layout_end(); }
function fields_customer():void { ?><div class="form-grid"><label>Nome completo ou empresa<input name="name" required></label><label>E-mail<input type="email" name="email"></label><label>Telefone<input name="phone"></label><label>Organização<input name="organization"></label><label>Origem<input name="source" placeholder="Indicação, site..."></label><label class="full">Observações<textarea name="notes"></textarea></label></div><?php }
function deals_page():void { if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(limit_reached('deals', "stage NOT IN ('won','lost')")){flash('error','Limite de oportunidades abertas atingido.');redirect('index.php?page=deals');}$customer=(int)($_POST['customer_id']??0);$check=db()->prepare('SELECT id FROM customers WHERE id=? AND company_id=?');$check->execute([$customer,tenant_id()]);if(!$check->fetch())$customer=null;$q=db()->prepare('INSERT INTO deals(company_id,customer_id,title,value_cents,stage,expected_date,notes) VALUES(?,?,?,?,?,?,?)');$q->execute([tenant_id(),$customer,post('title'),(int)round((float)str_replace(',','.',post('value'))*100),post('stage','new'),post('expected_date')?:null,post('notes')]);flash('success','Oportunidade criada.');redirect('index.php?page=deals');} layout_start('Oportunidades');$c=db()->prepare('SELECT id,name FROM customers WHERE company_id=? ORDER BY name');$c->execute([tenant_id()]);$customers=$c->fetchAll();$q=db()->prepare('SELECT d.*,c.name customer_name FROM deals d LEFT JOIN customers c ON c.id=d.customer_id AND c.company_id=d.company_id WHERE d.company_id=? ORDER BY d.created_at DESC');$q->execute([tenant_id()]);$rows=$q->fetchAll(); ?><div class="page-actions"><p>Mais oportunidades e resultados.</p><a class="btn primary" href="?page=deals&new=1">+ Nova oportunidade</a></div><?php if(isset($_GET['new'])): ?><section class="card form-card"><h3>Nova oportunidade</h3><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><label>Título<input name="title" required></label><label>Cliente<select name="customer_id"><option value="0">Sem cliente</option><?php foreach($customers as $x): ?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach; ?></select></label><label>Valor estimado (R$)<input name="value" type="number" step="0.01" min="0"></label><label>Etapa<select name="stage"><?php foreach(stage_labels() as $k=>$v): ?><option value="<?=$k?>"><?=e($v)?></option><?php endforeach; ?></select></label><label>Previsão de fechamento<input type="date" name="expected_date"></label><label class="full">Observações<textarea name="notes"></textarea></label></div><button class="btn primary">Salvar oportunidade</button></form></section><?php endif; ?><section class="card"><div class="table-wrap"><table><thead><tr><th>Oportunidade</th><th>Cliente</th><th>Etapa</th><th>Valor</th><th>Previsão</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['title'])?></strong></td><td><?=e($r['customer_name']?:'—')?></td><td><span class="badge <?=e($r['stage'])?>"><?=e(stage_label($r['stage']))?></span></td><td>R$ <?=number_format($r['value_cents']/100,2,',','.')?></td><td><?=e($r['expected_date']?date('d/m/Y',strtotime($r['expected_date'])):'—')?></td></tr><?php endforeach; ?></tbody></table></div></section><?php layout_end(); }
function tasks_page():void { if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(limit_reached('tasks', "status='pending'")){flash('error','Limite de tarefas ativas atingido.');redirect('index.php?page=tasks');}$q=db()->prepare('INSERT INTO tasks(company_id,title,description,due_date) VALUES(?,?,?,?)');$q->execute([tenant_id(),post('title'),post('description'),post('due_date')?:null]);flash('success','Tarefa adicionada.');redirect('index.php?page=tasks');} layout_start('Tarefas');$q=db()->prepare('SELECT * FROM tasks WHERE company_id=? ORDER BY status,due_date IS NULL,due_date');$q->execute([tenant_id()]);$rows=$q->fetchAll(); ?><div class="page-actions"><p>Organização e foco para os próximos passos.</p><a class="btn primary" href="?page=tasks&new=1">+ Nova tarefa</a></div><?php if(isset($_GET['new'])): ?><section class="card form-card"><h3>Nova tarefa</h3><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><label>Título<input name="title" required></label><label>Prazo<input name="due_date" type="date"></label><label class="full">Descrição<textarea name="description"></textarea></label></div><button class="btn primary">Salvar tarefa</button></form></section><?php endif; ?><section class="card"><div class="table-wrap"><table><thead><tr><th>Tarefa</th><th>Prazo</th><th>Status</th><th>Criada em</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['title'])?></strong><br><small><?=e($r['description'])?></small></td><td><?=e($r['due_date']?date('d/m/Y',strtotime($r['due_date'])):'—')?></td><td><span class="badge <?=$r['status']==='done'?'won':'new'?>"><?=e($r['status']==='done'?'Concluída':'Pendente')?></span></td><td><?=e(date('d/m/Y',strtotime($r['created_at'])))?></td></tr><?php endforeach; ?></tbody></table></div></section><?php layout_end(); }
function admin_page():void { if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
if(post('action')==='create_client'){
 $cname=post('company_name');$owner=post('owner_name');$email=strtolower(post('email'));$pass=(string)($_POST['password']??'');$plan=post('plan','free');$err='';
 if($cname===''||$owner==='') $err='Informe o nome da empresa e do responsável.';
 elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)) $err='E-mail de acesso inválido.';
 elseif(strlen($pass)<8) $err='A senha deve ter pelo menos 8 caracteres.';
 elseif(!in_array($plan,['free','pro','premium'],true)) $err='Plano inválido.';
 else { $ex=db()->prepare('SELECT 1 FROM users WHERE email=?'); $ex->execute([$email]); if($ex->fetch()) $err='Já existe um usuário com este e-mail.'; }
 if($err!==''){flash('error',$err);redirect('index.php?page=admin');}
 $pdo=db();$pdo->beginTransaction();
 try{
  $pdo->prepare('INSERT INTO companies(name,owner_name,email) VALUES(?,?,?)')->execute([$cname,$owner,$email]);
  $cid=(int)$pdo->lastInsertId();
  $pdo->prepare('INSERT INTO company_subscriptions(company_id,plan_code,assigned_by) VALUES(?,?,?)')->execute([$cid,$plan,current_user()['id']]);
  $pdo->prepare('INSERT INTO users(company_id,name,email,password_hash,role) VALUES(?,?,?,?,?)')->execute([$cid,$owner,$email,password_hash($pass,PASSWORD_DEFAULT),'owner']);
  $pdo->commit();
 }catch(Throwable $t){ if($pdo->inTransaction()) $pdo->rollBack(); throw $t; }
 audit('client_created','company',$cid,'Cliente criado com plano '.$plan.' e acesso '.$email);
 flash('success','Cliente "'.$cname.'" criado. Acesso: '.$email.' · Plano '.strtoupper($plan).'.');
 redirect('index.php?page=admin');
}
$company=(int)($_POST['company_id']??0);$plan=post('plan');$status=post('status','active');$q=db()->prepare('UPDATE companies SET status=? WHERE id=?');$q->execute([$status,$company]);$q=db()->prepare('INSERT INTO company_subscriptions(company_id,plan_code,assigned_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE plan_code=VALUES(plan_code),assigned_by=VALUES(assigned_by),status="active"');$q->execute([$company,$plan,current_user()['id']]);audit('company_updated','company',$company,'Plano/status atualizados');flash('success','Empresa atualizada e auditada.');redirect('index.php?page=admin');} layout_start('Administração global');$companies=db()->query('SELECT c.*,COALESCE(s.plan_code,"free") plan_code,(SELECT COUNT(*) FROM users u WHERE u.company_id=c.id) users_count,(SELECT COUNT(*) FROM customers x WHERE x.company_id=c.id) customers_count FROM companies c LEFT JOIN company_subscriptions s ON s.company_id=c.id ORDER BY c.created_at DESC')->fetchAll(); ?><section class="card form-card"><div class="card-head"><h3>Cadastrar novo cliente</h3></div><p style="margin:0 0 12px;color:#64748b">Cria a empresa, o login do responsável e o plano de uma vez. Anote a senha antes de salvar: ela não pode ser vista depois.</p><form method="post" autocomplete="off"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="create_client"><div class="form-grid"><label>Empresa / cliente<input name="company_name" required maxlength="160"></label><label>Nome do responsável<input name="owner_name" required maxlength="160"></label><label>E-mail de acesso<input type="email" name="email" required maxlength="190"></label><label>Senha de acesso (mín. 8)<input type="text" id="new-pass" name="password" required minlength="8" autocomplete="new-password"></label><label>Plano<select name="plan"><option value="free">Free</option><option value="pro">Pro</option><option value="premium">Premium</option></select></label><label>&nbsp;<button type="button" class="btn small" onclick="var a='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789',r=new Uint32Array(12),o='';crypto.getRandomValues(r);for(var i=0;i<12;i++)o+=a[r[i]%a.length];document.getElementById('new-pass').value=o;">Gerar senha</button></label></div><button class="btn primary">Criar cliente</button></form></section><div class="stats"><div class="stat"><span>Empresas</span><strong><?=count($companies)?></strong><small>contas cadastradas</small></div><div class="stat"><span>Ativas</span><strong><?=count(array_filter($companies,fn($x)=>$x['status']==='active'))?></strong><small>em operação</small></div><div class="stat"><span>Planos pagos</span><strong><?=count(array_filter($companies,fn($x)=>$x['plan_code']!=='free'))?></strong><small>Pro ou Premium</small></div></div><section class="card"><div class="card-head"><h3>Empresas cadastradas</h3></div><div class="table-wrap"><table><thead><tr><th>Empresa</th><th>Responsável</th><th>Plano</th><th>Uso</th><th>Ações</th></tr></thead><tbody><?php foreach($companies as $c): ?><tr><td><strong><?=e($c['name'])?></strong><br><small><?=e($c['email'])?></small></td><td><?=e($c['owner_name'])?></td><td><span class="badge <?=e($c['plan_code'])?>"><?=e(strtoupper($c['plan_code']))?></span><br><small><?=e($c['status'])?></small></td><td><?=e($c['customers_count'])?> clientes · <?=e($c['users_count'])?> usuários</td><td><form class="inline-form" method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="company_id" value="<?=$c['id']?>"><select name="plan"><option value="free" <?=$c['plan_code']==='free'?'selected':''?>>Free</option><option value="pro" <?=$c['plan_code']==='pro'?'selected':''?>>Pro</option><option value="premium" <?=$c['plan_code']==='premium'?'selected':''?>>Premium</option></select><select name="status"><option value="active" <?=$c['status']==='active'?'selected':''?>>Ativa</option><option value="suspended" <?=$c['status']==='suspended'?'selected':''?>>Suspensa</option></select><button class="btn small">Salvar</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php layout_end(); }
function stage_labels():array{return ['new'=>'Novo contato','contacted'=>'Primeiro contato','qualified'=>'Qualificação','proposal'=>'Proposta enviada','negotiation'=>'Negociação','won'=>'Venda ganha','lost'=>'Venda perdida'];} function stage_label(string $s):string{return stage_labels()[$s]??$s;}
